using Seamless.Management;
using Seamless.Management.Server;

namespace Management.Tests;

[Collection("AuditStorage")]
public sealed class AuditReadIdentity{
    private static string Root()=>Path.Combine(Environment.GetEnvironmentVariable("SEAMLESS_MANAGEMENT_TEST_ROOT")!,Guid.NewGuid().ToString("N"));
    private static AuditReadKey Key(){var at=new DateTimeOffset(2026,11,4,0,0,0,TimeSpan.Zero);return new(at,at.AddMinutes(1),Guid.Parse("12345678-1234-1234-1234-123456789abc"),"user","sales","query","code",7);}
    private static AuditReadKey Shift(AuditReadKey key)=>key with{WindowStart=key.WindowStart.ToOffset(TimeSpan.FromHours(9)),WindowEnd=key.WindowEnd.ToOffset(TimeSpan.FromHours(9))};
    [Fact]public void EqualKeysWithDifferentOffsetsShareOneSummary(){var key=Key();var same=Shift(key);Assert.Equal(key,same);using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");store.ApplyReadSummaryBatch(Guid.NewGuid(),[new(key,10)]);store.ApplyReadSummaryBatch(Guid.NewGuid(),[new(same,3)]);Assert.Equal(13,store.ReadSummary(key)!.Count);Assert.Equal(13,store.ReadSummary(same)!.Count);Assert.Single(store.ReadSummaries(new()).Items);}
    [Fact]public void EqualBatchesWithDifferentOffsetsAreIdempotentAfterRestart(){var root=Root();var key=Key();var id=Guid.NewGuid();using(var store=ManagementStore.Initialize(root,"admin","TestPassword-123")){Assert.True(store.ApplyReadSummaryBatch(id,[new(key,10)]));}using var reopened=new ManagementStore(root);Assert.False(reopened.ApplyReadSummaryBatch(id,[new(Shift(key),10)]));Assert.Equal(10,reopened.ReadSummary(Shift(key))!.Count);Assert.Equal("Conflict",Assert.Throws<ManagementException>(()=>reopened.ApplyReadSummaryBatch(id,[new(key,11)])).Code);}
    [Fact]public void CanonicalIdentityKeepsNullEmptyFieldBoundariesAndCodeUnitsDistinct(){var key=Key();Assert.Equal(Seamless.Management.Server.AuditReadIdentity.Id(key),Seamless.Management.Server.AuditReadIdentity.Id(Shift(key)));var variants=new[]{key,key with{SubjectId="u",Database="sersales"},key with{CodeVersion=null},key with{CodeVersion=""},key with{PolicyVersion=null},key with{PolicyVersion=0},key with{QueryId="\uD800"},key with{QueryId="\uD801"},key with{QueryId="\uFFFD"}};Assert.Equal(variants.Length,variants.Select(Seamless.Management.Server.AuditReadIdentity.Id).Distinct().Count());Assert.NotEqual(Seamless.Management.Server.AuditReadIdentity.BatchHash([new(key,1),new(key,2)]),Seamless.Management.Server.AuditReadIdentity.BatchHash([new(key,2),new(key,1)]));}
    [Fact]public void ExplicitUpgradeMergesLegacyKeysAndPreservesAuditAndBackup(){
        var root=Root();var key=Key();var first=Guid.NewGuid();var second=Guid.NewGuid();var at=key.WindowStart;var item=new AuditEvent(Guid.NewGuid(),null,at,at,Guid.NewGuid(),"user","sales","orders",AuditAction.DataChange,AuditOutcome.Succeeded,7,"code",null,"OK");Guid instance;long sequence;
        using(var old=ManagementStore.InitializeAuditLegacy(root,"admin","TestPassword-123")){instance=old.InstanceId;sequence=old.AppendAudit(item);old.ApplyReadSummaryBatch(first,[new(key,10)]);old.ApplyReadSummaryBatch(second,[new(Shift(key),3)]);Assert.Equal(2,old.ReadSummaries(new()).Items.Length);old.Write(()=>old.Put("probe","origin",new SourceFile("preserved.cs","source")));}
        using(var unchanged=new ManagementStore(root)){Assert.Equal(4,unchanged.Format);Assert.Equal(2,unchanged.ReadSummaries(new()).Items.Length);}ManagementStoreUpgrade.Upgrade(root,root+"-backup");
        using(var store=new ManagementStore(root)){Assert.Equal(5,store.Format);Assert.Equal(instance,store.InstanceId);Assert.Equal("source",store.Read<SourceFile>("probe","origin")!.Text);var summary=Assert.Single(store.ReadSummaries(new()).Items);Assert.Equal(1,summary.Sequence);Assert.Equal(13,summary.Count);Assert.Equal(13,store.ReadSummary(Shift(key))!.Count);Assert.Equal(sequence,store.AppendAudit(item));Assert.Contains(store.AuditEvents(new()).Items,row=>row.EventId==item.EventId);var batch=Guid.NewGuid();store.ApplyReadSummaryBatch(batch,[new(Shift(key),7)]);Assert.False(store.ApplyReadSummaryBatch(batch,[new(key,7)]));Assert.Equal(20,store.ReadSummary(key)!.Count);}
        using var backup=new ManagementStore(root+"-backup");Assert.Equal(4,backup.Format);Assert.Equal(2,backup.ReadSummaries(new()).Items.Length);Assert.Single(backup.AuditEvents(new()).Items);Assert.Equal(instance,backup.InstanceId);
    }
    [Fact]public void UnverifiableLegacyBatchDoesNotAddCountsAgain(){
        var root=Root();var key=Key();var id=Guid.NewGuid();using(var old=ManagementStore.InitializeAuditLegacy(root,"admin","TestPassword-123")){old.ApplyReadSummaryBatch(id,[new(key,10)]);var database=(ManagementAuditDatabase)typeof(ManagementStore).GetField("database",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!.GetValue(old)!;old.Write(()=>database.AuditBatches[new(id)]=new(id,new string('0',64)));}ManagementStoreUpgrade.Upgrade(root,root+"-backup");using var store=new ManagementStore(root);Assert.Equal("LegacyReplayUnverifiable",Assert.Throws<ManagementException>(()=>store.ApplyReadSummaryBatch(id,[new(Shift(key),10)])).Code);Assert.Equal(10,store.ReadSummary(key)!.Count);
    }
    [Theory][InlineData("OldMoved")][InlineData("NewInstalled")][InlineData("Committed")]
    public void FailedUpgradeRestoresFormatFourAndItsSummaryRows(string phase){var root=Root();using(var old=ManagementStore.InitializeAuditLegacy(root,"admin","TestPassword-123")){old.ApplyReadSummaryBatch(Guid.NewGuid(),[new(Key(),10)]);}ManagementStoreUpgrade.Checkpoint=current=>{if(current==phase){throw new IOException("injected "+phase);}};try{Assert.Throws<IOException>(()=>ManagementStoreUpgrade.Upgrade(root,root+"-backup"));}finally{ManagementStoreUpgrade.Checkpoint=null;}using var restored=new ManagementStore(root);Assert.Equal(4,restored.Format);Assert.Equal(10,Assert.Single(restored.ReadSummaries(new()).Items).Count);}
    [Fact]public void OverflowDuringMergeKeepsOldFormatAndCounts(){var root=Root();using(var old=ManagementStore.InitializeAuditLegacy(root,"admin","TestPassword-123")){old.ApplyReadSummaryBatch(Guid.NewGuid(),[new(Key(),long.MaxValue)]);old.ApplyReadSummaryBatch(Guid.NewGuid(),[new(Shift(Key()),1)]);}Assert.Throws<OverflowException>(()=>ManagementStoreUpgrade.Upgrade(root,root+"-backup"));using var store=new ManagementStore(root);Assert.Equal(4,store.Format);Assert.Equal(2,store.ReadSummaries(new()).Items.Length);Assert.True(Directory.Exists(root+"-backup"));}
    [Theory][InlineData(0)][InlineData(160)]public void EmptyAndChunkedLegacyAuditTablesAreCopied(int count){var root=Root();var key=Key();using(var old=ManagementStore.InitializeAuditLegacy(root,"admin","TestPassword-123")){for(var start=0;start<count;start+=32){var first=start;old.Write(()=>{for(var index=first;index<Math.Min(first+32,count);index++){var at=key.WindowStart;old.AppendAuditInside(new(Guid.NewGuid(),null,at,at,key.AuthorityId,"user","sales",null,AuditAction.Read,AuditOutcome.Succeeded,null,null,null,"Fixture"));}});old.ApplyReadSummaryBatch(Guid.NewGuid(),Enumerable.Range(first,Math.Min(32,count-first)).Select(index=>new AuditReadDelta(key with{QueryId="query-"+index},index+1)).ToArray());}}ManagementStoreUpgrade.Upgrade(root,root+"-backup");using var current=new ManagementStore(root);Assert.Equal(5,current.Format);var total=0;long before=0,ceiling=0;while(true){var page=current.ReadSummaries(new(Before:before,Ceiling:ceiling));total+=page.Items.Length;before=page.NextBefore;ceiling=page.Ceiling;if(!page.HasMore){break;}}Assert.Equal(count,total);for(var index=0;index<count;index++){Assert.Equal(index+1,current.ReadSummary(key with{QueryId="query-"+index})!.Count);}var events=0;before=0;ceiling=0;while(true){var page=current.AuditEvents(new(Before:before,Ceiling:ceiling));events+=page.Items.Length;before=page.NextBefore;ceiling=page.Ceiling;if(!page.HasMore){break;}}Assert.Equal(count+1,events);}
    [Fact]public async Task UpgradeKeepsCommittedUserRowsAndPendingUpdateAudit(){
        var root=Root();DefinitionVersion before;Guid wal;
        Definition query(string id,string body,bool writes=false)=>new(id,"Native",DefinitionKind.Query,"Model.Query","Run",new("1",[new("query.cs","using System.Linq;using Seamless.Management.Server;namespace Model;public static class Query{public static int Run(ManagementExecutionContext context){"+body+"}}")],[]),writes);
        UserAccount login(Seamless.Management.Server.ManagementService service)=>service.Authenticate(service.Login(new("admin","TestPassword-123")).Token);
        using(var old=ManagementStore.InitializeAuditLegacy(root,"admin","TestPassword-123"))using(var service=new Seamless.Management.Server.ManagementService(old){AuditDeliveryPaused=true}){var user=login(service);NativeWorkflow.Publish(service,user,NativeWorkflow.Database());NativeWorkflow.Publish(service,user,query("insert","context.GetDatabase<Db>().Rows.Add(new Records.Row(1,9));return 9;",true));NativeWorkflow.Publish(service,user,query("sum","return context.GetDatabase<Db>().Rows.Sum(row=>row.Value);"));_=service.Execute(user,new("insert",null,ManagementJson.Element(new{})),CancellationToken.None).ToArray();Assert.Empty(old.AuditEvents(new(Action:AuditAction.DataChange)).Items);before=service.GetDefinition(user,"db");wal=Assert.Single(old.List<AuditOrigin>("auditOrigin").Items).WalId;}
        ManagementStoreUpgrade.Upgrade(root,root+"-backup");using var current=new ManagementStore(root);Assert.Equal(wal,Assert.Single(current.List<AuditOrigin>("auditOrigin").Items).WalId);using var restarted=new Seamless.Management.Server.ManagementService(current);var actor=login(restarted);var active=restarted.GetDefinition(actor,"db");Assert.Equal(before.Version,active.Version);Assert.Equal(before.ArtifactHash,active.ArtifactHash);Assert.Equal(before.StoragePath,active.StoragePath);Assert.Equal(9,Assert.Single(restarted.Execute(actor,new("sum",null,ManagementJson.Element(new{})),CancellationToken.None)).Value.GetInt32());using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(30));while(current.AuditEvents(new(Action:AuditAction.DataChange)).Items.Length==0){await Task.Delay(30,timeout.Token);}Assert.Single(current.AuditEvents(new(Action:AuditAction.DataChange)).Items);
    }
}
